    { q: "Welche Photorezeptoren sind für das Farbensehen zuständig und in der Fovea konzentriert?", o: ["Stäbchen", "Zapfen", "Ganglienzellen", "Bipolarzellen"], a: 1, e: "Drei Zapfentypen (S, M, L)." },
    { q: "Welche Reihenfolge beschreibt die HPA-Achse korrekt?", o: ["ACTH → CRH → Cortisol", "CRH → ACTH → Cortisol", "Cortisol → CRH → ACTH", "Adrenalin → ACTH → CRH"], a: 1, e: "Hypothalamus (CRH) → Hypophyse (ACTH) → Nebennierenrinde (Cortisol)." },
    { q: "Wo liegt die „innere Uhr“ für circadiane Rhythmen?", o: ["Zirbeldrüse", "Nucleus suprachiasmaticus im Hypothalamus", "Cerebellum", "Amygdala"], a: 1, e: "Der SCN steuert u. a. die Melatoninausschüttung der Zirbeldrüse." },
    { q: "Welches EEG-Merkmal ist typisch für Schlafstadium N2?", o: ["Alpha-Wellen", "Schlafspindeln und K-Komplexe", "Durchgehende Delta-Wellen", "Sägezahnwellen und Atonie"], a: 1, e: "N3 = Delta, REM = desynchronisiert mit Muskelatonie." },
    { q: "Wie lange dauert ein Schlafzyklus etwa?", o: ["20 Minuten", "90 Minuten", "3 Stunden", "8 Stunden"], a: 1, e: "Ca. 4–6 Zyklen pro Nacht." },
    { q: "Welche Beeinträchtigung zeigte Patient H. M. nach der Operation NICHT?", o: ["Schwere anterograde Amnesie", "Unfähigkeit, neue Fakten zu lernen", "Unfähigkeit, neue motorische Fertigkeiten zu lernen", "Teilweise retrograde Amnesie"], a: 2, e: "Prozedurales Lernen (Spiegelzeichnen) war erhalten." },
    { q: "Welcher Rezeptor gilt als „Koinzidenzdetektor“ bei der LTP?", o: ["GABA_A", "NMDA", "Nikotinischer ACh-Rezeptor", "D2"], a: 1, e: "Benötigt Glutamatbindung und Depolarisation (Aufhebung des Mg²⁺-Blocks)." },
    { q: "Dopaminneurone feuern nach Schultz verstärkt, wenn …", o: ["eine erwartete Belohnung eintrifft", "eine unerwartete Belohnung eintrifft", "keine Belohnung erwartet wird und keine kommt", "Schmerz auftritt"], a: 1, e: "Sie codieren den Belohnungsvorhersagefehler." },
    { q: "Ein Split-Brain-Patient sieht ein Bild im linken Gesichtsfeld. Was kann er typischerweise?", o: ["Es benennen", "Es mit der linken Hand ertasten/auswählen", "Es mit der rechten Hand zeichnen", "Nichts davon"], a: 1, e: "Linkes Gesichtsfeld → rechte Hemisphäre → steuert linke Hand; Sprache meist links." },
    { q: "Welche Struktur ist zentral für Furchtkonditionierung?", o: ["Cerebellum", "Amygdala", "Corpus callosum", "Okzipitallappen"], a: 1, e: "LeDoux; Läsionen verhindern konditionierte Furcht." },
    { q: "Die Somatische-Marker-Hypothese stammt von …", o: ["LeDoux", "Damasio", "Hebb", "Sperry"], a: 1, e: "Körperliche Signale leiten Entscheidungen; Iowa Gambling Task, vmPFC-Patienten." }
